/* seidel-2d.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "seidel-2d.h"

/* ------------------------------------------------------------------------
 * Tunable kernel parameters
 *
 * TUNING_I_BLOCK:
 *   Row blocking factor. This tiles the i (row) dimension but preserves
 *   the global row-major execution order of the original kernel.
 *
 * TUNING_J_UNROLL:
 *   Unrolling factor used in the j (column) loop. Only the value 4 is
 *   specialized below; other values fall back to the scalar loop.
 * -------------------------------------------------------------------- */
#ifndef TUNING_I_BLOCK
# define TUNING_I_BLOCK 32
#endif

#ifndef TUNING_J_UNROLL
# define TUNING_J_UNROLL 4
#endif


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Create a restrict-qualified alias to help the compiler's alias
     analysis without changing the externally visible interface. */
  DATA_TYPE (* restrict A_)[n] = A;

  /* The initialization has no cross-iteration dependencies, so it is
     safe to parallelize if the user compiles with OpenMP enabled.
     Without -fopenmp, this pragma is ignored. */
#pragma omp parallel for private(j) schedule(static)
  for (i = 0; i < n; i++) {
    DATA_TYPE * restrict Ai = A_[i];
    for (j = 0; j < n; j++)
      Ai[j] = ((DATA_TYPE) i * (j + 2) + 2) / n;
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimization notes:
   - Uses a restrict-qualified 2D alias for A to improve alias analysis.
   - Hoists the factor 1/9 out of the loops.
   - Tiles the i (row) dimension with configurable block size
     (TUNING_I_BLOCK) while preserving the global row-major order.
   - Manually unrolls the j (column) loop by 4 (TUNING_J_UNROLL == 4)
     to expose more instruction-level parallelism.

   Importantly, the lexicographic (t, i, j) update order of all interior
   points is identical to the original triple loop: within each time
   step, rows are processed from top to bottom and, inside each row,
   columns from left to right. This preserves the in-place Gauss–Seidel
   semantics and therefore the numerical results.
*/
static
void kernel_seidel_2d[[gnu::flatten, gnu::noinline]](int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  /* Alias with restrict-qualified pointer for better optimization. */
  DATA_TYPE (* restrict A_)[n] = A;

  /* Hoist the constant division out of the loops. The compiler would
     typically do this as well, but making it explicit clarifies intent. */
  const DATA_TYPE inv9 = SCALAR_VAL(1.0) / SCALAR_VAL(9.0);

#pragma scop
  for (int t = 0; t <= _PB_TSTEPS - 1; t++)
  {
    /* Tile the row dimension. Tilings are chosen so that the relative
       order of all (i, j) pairs is the same as in the original code. */
    for (int i_block = 1; i_block < _PB_N - 1; i_block += TUNING_I_BLOCK)
    {
      int i_block_end = i_block + TUNING_I_BLOCK;
      if (i_block_end > _PB_N - 1)
        i_block_end = _PB_N - 1; /* exclusive upper bound for i */

      for (int i = i_block; i < i_block_end; ++i)
      {
        DATA_TYPE * restrict A_im1 = A_[i - 1];
        DATA_TYPE * restrict A_i   = A_[i];
        DATA_TYPE * restrict A_ip1 = A_[i + 1];

        int j      = 1;
        int j_end  = _PB_N - 1;  /* exclusive upper bound for j (== n-1) */

#if TUNING_J_UNROLL == 4
        /* Manually unroll the inner loop by 4. Each update for column
           j+k uses results from earlier columns (Gauss–Seidel), but
           within this unrolled body the four updates are still executed
           strictly in increasing column order, so the data dependencies
           are respected exactly as in the original loop. */
        for (; j + 3 < j_end; j += 4)
        {
          const int j0 = j;
          const int j1 = j + 1;
          const int j2 = j + 2;
          const int j3 = j + 3;

          const int jm1_0 = j0 - 1;
          const int jm1_1 = j1 - 1;
          const int jm1_2 = j2 - 1;
          const int jm1_3 = j3 - 1;

          const int jp1_0 = j0 + 1;
          const int jp1_1 = j1 + 1;
          const int jp1_2 = j2 + 1;
          const int jp1_3 = j3 + 1;

          A_i[j0] = (A_im1[jm1_0] + A_im1[j0]    + A_im1[jp1_0]
                   + A_i  [jm1_0] + A_i  [j0]    + A_i  [jp1_0]
                   + A_ip1[jm1_0] + A_ip1[j0]    + A_ip1[jp1_0]) * inv9;

          A_i[j1] = (A_im1[jm1_1] + A_im1[j1]    + A_im1[jp1_1]
                   + A_i  [jm1_1] + A_i  [j1]    + A_i  [jp1_1]
                   + A_ip1[jm1_1] + A_ip1[j1]    + A_ip1[jp1_1]) * inv9;

          A_i[j2] = (A_im1[jm1_2] + A_im1[j2]    + A_im1[jp1_2]
                   + A_i  [jm1_2] + A_i  [j2]    + A_i  [jp1_2]
                   + A_ip1[jm1_2] + A_ip1[j2]    + A_ip1[jp1_2]) * inv9;

          A_i[j3] = (A_im1[jm1_3] + A_im1[j3]    + A_im1[jp1_3]
                   + A_i  [jm1_3] + A_i  [j3]    + A_i  [jp1_3]
                   + A_ip1[jm1_3] + A_ip1[j3]    + A_ip1[jp1_3]) * inv9;
        }
#endif /* TUNING_J_UNROLL == 4 */

        /* Remainder (or full) scalar loop for the last columns. For
           TUNING_J_UNROLL != 4 this loop performs the entire work. */
        for (; j < j_end; ++j)
        {
          const int jm1 = j - 1;
          const int jp1 = j + 1;

          A_i[j] = (A_im1[jm1] + A_im1[j] + A_im1[jp1]
                  + A_i  [jm1] + A_i  [j] + A_i  [jp1]
                  + A_ip1[jm1] + A_ip1[j] + A_ip1[jp1]) * inv9;
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_seidel_2d (tsteps, n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}

