/* seidel-2d.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "seidel-2d.h"


/* Array initialization.
 *
 * Optimizations:
 * - Hoist 1/n out of the inner loops and use a multiplication instead of
 *   a division inside the loop body.
 * - Use a row pointer (Ai) to avoid recomputing the row base address.
 * - Mark Ai as restrict to help the compiler with alias analysis.
 * - Keep memory access contiguous in the inner loop (good cache locality).
 * - The loop is trivially parallelizable; an OpenMP pragma is safe here.
 */
static
void init_array (int n,
                 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  const DATA_TYPE inv_n = SCALAR_VAL(1.0) / (DATA_TYPE)n;
  const DATA_TYPE two   = SCALAR_VAL(2.0);

  /* Independent iterations: safe to parallelize if compiled with OpenMP.
   * Without -fopenmp this pragma is ignored by the compiler.
   */
  #pragma omp parallel for schedule(static) private(j)
  for (i = 0; i < n; ++i)
  {
    DATA_TYPE * restrict Ai = A[i];
    const DATA_TYPE i_val = (DATA_TYPE)i;

    for (j = 0; j < n; ++j)
    {
      Ai[j] = (i_val * (DATA_TYPE)(j + 2) + two) * inv_n;
    }
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
                 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimization strategy for the Gauss–Seidel 9-point stencil:
 *
 * - We must preserve the in-place Gauss-Seidel update order:
 *   for a given time step t, elements are updated in lexicographic
 *   (i,j) order, and each update uses already-updated neighbors in
 *   row i-1 and column j-1, but not yet updated neighbors in row i+1
 *   and column j+1.
 *
 * - Because of these strong loop-carried dependences along both i and j,
 *   the spatial loops cannot be safely parallelized or vectorized with
 *   directives such as omp parallel for / simd or ivdep without changing
 *   the numerical results.
 *
 * - We therefore focus on single-thread performance and data locality:
 *   * Use row pointers (prev, curr, next) to avoid repeated address
 *     computations on A[i][j].
 *   * Implement a sliding 3×3 window in registers along the j dimension.
 *     For each of the three rows involved in the stencil (i-1, i, i+1),
 *     we keep three neighboring values in registers and slide them
 *     one position to the right at each j iteration.
 *   * Carefully maintain the Gauss–Seidel semantics:
 *       - left neighbor A[i][j-1]: updated in the current timestep
 *         for j > 1 (or boundary for j == 1),
 *       - center A[i][j]: old value at this timestep,
 *       - right neighbor A[i][j+1]: old value at this timestep.
 *     The sliding-window logic is constructed so that these invariants
 *     hold at the start of each j iteration.
 *
 * - This reduces the number of loads per inner iteration significantly
 *   while preserving the exact update order and in-place behaviour.
 */
static
void kernel_seidel_2d[[gnu::flatten, gnu::noinline]](int tsteps,
                      int n,
                      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i;

#pragma scop
  const int t_max   = _PB_TSTEPS;
  const int n_inner = _PB_N;
  const DATA_TYPE denom = SCALAR_VAL(9.0);

  for (t = 0; t < t_max; ++t)
  {
    /* i loop cannot be parallelized because row i depends on row i-1
     * updated in the same time step (Gauss–Seidel along i).
     */
    for (i = 1; i <= n_inner - 2; ++i)
    {
      /* Pointers to the three rows involved in the stencil. */
      DATA_TYPE * restrict prev = A[i - 1];
      DATA_TYPE * restrict curr = A[i];
      DATA_TYPE * restrict next = A[i + 1];

      const int j_end = n_inner - 2;

      /* Initialize the sliding window for j = 1. */
      int j = 1;

      /* Vertical neighbors in row i-1. */
      DATA_TYPE pjm1 = prev[j - 1]; /* prev[j-1] */
      DATA_TYPE pj   = prev[j];     /* prev[j]   */
      DATA_TYPE pjp1 = prev[j + 1]; /* prev[j+1] */

      /* Vertical neighbors in row i+1. */
      DATA_TYPE njm1 = next[j - 1]; /* next[j-1] */
      DATA_TYPE nj   = next[j];     /* next[j]   */
      DATA_TYPE njp1 = next[j + 1]; /* next[j+1] */

      /* Horizontal window in current row i.
       *
       * Invariants at the start of each j iteration:
       *   c_left      = A[i][j-1] after this time step (new for j>1,
       *                   boundary for j==1),
       *   cj_old      = A[i][j]   value from previous time step,
       *   c_right_old = A[i][j+1] value from previous time step.
       */
      DATA_TYPE c_left      = curr[j - 1]; /* boundary A[i][0], never updated */
      DATA_TYPE cj_old      = curr[j];     /* A[i][1] old value               */
      DATA_TYPE c_right_old = curr[j + 1]; /* A[i][2] old value               */

      for (j = 1; j <= j_end; ++j)
      {
        /* Compute new value for A[i][j] using 3×3 stencil. */
        DATA_TYPE new_center =
          (pjm1 + pj + pjp1 +
           c_left + cj_old + c_right_old +
           njm1 + nj + njp1) / denom;

        curr[j] = new_center;

        /* Prepare sliding window state for next j (i.e., j+1). */
        if (j < j_end)
        {
          /* Advance vertical windows (rows i-1 and i+1) by one column. */
          pjm1 = pj;
          pj   = pjp1;
          pjp1 = prev[j + 1 + 1];   /* prev[j+2] */

          njm1 = nj;
          nj   = njp1;
          njp1 = next[j + 1 + 1];   /* next[j+2] */

          /* Advance horizontal window on current row i.
           *
           * At this point:
           *   - new_center is the updated A[i][j],
           *   - c_right_old is A[i][j+1] old,
           *   - curr[j+2]   is A[i][j+2] old (not yet updated).
           *
           * For iteration j+1 we need:
           *   c_left      = A[i][(j+1)-1]   = A[i][j]   new_center,
           *   cj_old      = A[i][j+1] old   = c_right_old,
           *   c_right_old = A[i][j+2] old   = curr[j+2].
           */
          c_left      = new_center;
          cj_old      = c_right_old;
          c_right_old = curr[j + 1 + 1];   /* curr[j+2] */
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_seidel_2d (tsteps, n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
