  /* Each (i,j) element is written exactly once, so the outer loop can be
     safely parallelized. */
#pragma omp parallel for private(j) schedule(static)
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      A_[i][j] = ((DATA_TYPE) i * (j + 2) + 2) / (DATA_TYPE) n;
}


