/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimization overview:
 * - Preserve the original in-place Gauss–Seidel update order exactly.
 * - Use a restrict-qualified VLA pointer to aid alias analysis.
 * - For each row, cache three consecutive rows (i-1, i, i+1) as pointers.
 * - Implement a sliding 3x3 window in registers along the j (column)
 *   dimension. This avoids reloading all 9 stencil elements for every
 *   point:
 *     * We load the full 3x3 neighborhood once for j = 1.
 *     * As we move from j to j+1 we shift the window right and load
 *       only three new elements (the new rightmost column).
 * - The update order within (t, i, j) is unchanged; at each (i,j) we use
 *   exactly the same neighbor values as the original code would use.
 */
static
void kernel_seidel_2d[[gnu::flatten, gnu::noinline]](int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i;
  (void)tsteps; /* Loop bound is taken from PolyBench macros (_PB_TSTEPS). */

  /* Local restrict-qualified view of the 2D array.
     The second dimension is the runtime size 'n' (VLA). */
  DATA_TYPE (*restrict A_)[n] = A;

#pragma scop
  for (t = 0; t <= _PB_TSTEPS - 1; t++)
  {
    /* Iterate over interior rows (boundaries are not updated). */
    for (i = 1; i <= _PB_N - 2; i++)
    {
      /* Pointers to the three rows involved in the 3x3 stencil. */
      DATA_TYPE *restrict Ai_1 = A_[i-1]; /* row i-1 */
      DATA_TYPE *restrict Ai   = A_[i];   /* row i   */
      DATA_TYPE *restrict Ai1  = A_[i+1]; /* row i+1 */

      /* We will slide a 3x3 window across the columns. For each column j,
         the window contains:
             up_left   = A[i-1][j-1]
             up_mid    = A[i-1][j]
             up_right  = A[i-1][j+1]
             mid_left  = A[i  ][j-1]
             mid_mid   = A[i  ][j]
             mid_right = A[i  ][j+1]
             down_left = A[i+1][j-1]
             down_mid  = A[i+1][j]
             down_right= A[i+1][j+1]

         Between j and j+1 we:
         - Shift each row's triple (left, mid, right) one step left.
         - Load only the three new rightmost values from memory.
         - Set mid_left to the newly updated A[i][j] so that the next
           iteration uses the most recent Gauss–Seidel value, exactly as
           in the original lexicographic update.
       */
      DATA_TYPE up_left, up_mid, up_right;
      DATA_TYPE mid_left, mid_mid, mid_right;
      DATA_TYPE down_left, down_mid, down_right;

      /* Last interior column index: j = 1 .. j_end */
      const int j_end = _PB_N - 2;

      /* Initialize window for j = 1.  The boundary columns (0 and n-1)
         are never updated and retain their initial values. */
      up_left   = Ai_1[0];
      up_mid    = Ai_1[1];
      up_right  = Ai_1[2];

      mid_left  = Ai[0];  /* boundary (unchanged during the kernel) */
      mid_mid   = Ai[1];  /* center for j=1: old Gauss–Seidel value */
      mid_right = Ai[2];

      down_left  = Ai1[0];
      down_mid   = Ai1[1];
      down_right = Ai1[2];

      int j;

      /* Process all interior columns except the last one.
         Loop invariant at start of each iteration j:
           - The *_left/*_mid/*_right variables hold the exact values
             A[.][j-1], A[.][j], A[.][j+1] that the original code would
             see at the beginning of iteration j. */
      for (j = 1; j < j_end; ++j)
      {
        DATA_TYPE new_mid_mid =
          (up_left + up_mid + up_right +
           mid_left + mid_mid + mid_right +
           down_left + down_mid + down_right) / SCALAR_VAL(9.0);

        /* In-place Gauss–Seidel update, as in the original code. */
        Ai[j] = new_mid_mid;

        /* Slide the 3x3 window one column to the right to prepare for j+1.
           Only three new elements (column j+1+1 = j+2) need to be loaded. */

        /* Upper row window: (j-1,j,j+1) -> (j,j+1,j+2). */
        up_left   = up_mid;
        up_mid    = up_right;
        up_right  = Ai_1[j+2];

        /* Middle row window:
             - Left neighbor becomes the value we just computed at A[i][j].
             - Middle/right shift left and we load the new rightmost value. */
        mid_left  = new_mid_mid;  /* updated A[i][j] */
        mid_mid   = mid_right;    /* old A[i][j+1] */
        mid_right = Ai[j+2];      /* old A[i][j+2] */

        /* Lower row window: same pattern as upper row. */
        down_left  = down_mid;
        down_mid   = down_right;
        down_right = Ai1[j+2];
      }

      /* Handle the last interior column j = j_end.
         After the previous loop, the window variables already correspond
         to column j_end, so we just perform the final stencil update. */
      if (j_end >= 1)
      {
        DATA_TYPE new_mid_mid =
          (up_left + up_mid + up_right +
           mid_left + mid_mid + mid_right +
           down_left + down_mid + down_right) / SCALAR_VAL(9.0);

        Ai[j_end] = new_mid_mid;
      }
    }
  }
#pragma endscop

}


