/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use a sliding-window scheme along j to reuse already loaded values
     from the three stencil rows (i-1, i, i+1) instead of reloading
     all 9 neighbors for every grid point.
   - Replace division by a constant with multiplication by its reciprocal.
   - Use row pointers to improve locality and enable better compiler
     optimizations.
   The iteration order (t, then i, then j increasing) is preserved
   exactly, so the Gauss-Seidel update semantics are unchanged.
*/
static
void kernel_seidel_2d[[gnu::flatten, gnu::noinline]](int tsteps,
                      int n,
                      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i, j;

  /* Precompute 1/9 as a scalar of the appropriate type. */
  const DATA_TYPE inv9 = SCALAR_VAL(1.0) / SCALAR_VAL(9.0);

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
  {
    /* Each time step depends on the results of the previous time step,
       so the t-loop must remain sequential. */
    for (i = 1; i <= _PB_N - 2; i++)
    {
      /* Row pointers for better cache behavior and fewer address
         calculations. These rows do not alias each other. */
      DATA_TYPE * restrict Aim1 = A[i-1];
      DATA_TYPE * restrict Ai   = A[i];
      DATA_TYPE * restrict Aip1 = A[i+1];

      /* Initialize a 3x3 sliding window for j = 1.
         At the start of the j-loop, the following invariants hold:

           prev_* = value at column j-1
           curr_* = value at column j

         where '*' ∈ {im1, i, ip1} refers to rows i-1, i, and i+1. */

      DATA_TYPE prev_im1 = Aim1[0];
      DATA_TYPE curr_im1 = Aim1[1];

      DATA_TYPE prev_i   = Ai[0];
      DATA_TYPE curr_i   = Ai[1];

      DATA_TYPE prev_ip1 = Aip1[0];
      DATA_TYPE curr_ip1 = Aip1[1];

      for (j = 1; j <= _PB_N - 2; j++)
      {
        const int jp1 = j + 1;

        /* Load the "right" column of the 3x3 stencil for this j.
           These are the only new elements we need to fetch; the
           "left" and "center" columns are already in registers. */
        DATA_TYPE next_im1 = Aim1[jp1];
        DATA_TYPE next_i   = Ai[jp1];
        DATA_TYPE next_ip1 = Aip1[jp1];

        /* Compute the 3x3 average using the sliding window.  The value
           curr_i is read *before* Ai[j] is updated, matching the
           original Gauss-Seidel semantics. */
        DATA_TYPE sum = prev_im1 + curr_im1 + next_im1
                      + prev_i   + curr_i   + next_i
                      + prev_ip1 + curr_ip1 + next_ip1;

        Ai[j] = sum * inv9;

        /* Shift the window one column to the right for the next j.
           For row i (the middle row), the new value just written to
           Ai[j] must be used as the left neighbor (A[i][j-1]) in the
           next iteration, while A[i][j+1] remains the "center" old
           value. This exactly reproduces the original update order:

             - A[i][j-1]: already updated (new)
             - A[i][j]  : current point (old when read, then updated)
             - A[i][j+1]: not yet updated (old)
        */
        prev_im1 = curr_im1;
        curr_im1 = next_im1;

        prev_i   = Ai[j];   /* use newly updated value */
        curr_i   = next_i;  /* still old */

        prev_ip1 = curr_ip1;
        curr_ip1 = next_ip1;
      }
    }
  }
#pragma endscop

}


